"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
@'
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const baseline = [{\"path\":\"archive-plan.md\",\"bytes\":1878,\"sha256\":\"787faac251ba594ef9a5fa1eac5980cdebb9c5c2666215e28fbe45c3f6701990\"},{\"path\":\"draft-status.md\",\"bytes\":372,\"sha256\":\"3b2b75ae4790d52860acb9c3024754bc25e7952f4d3769b34b62c448f3548c43\"},{\"path\":\"evidence/copy-log.json\",\"bytes\":281,\"sha256\":\"e150a7088e29df9810689012a296b75d3edcc65be2a8e5e6da37429694538801\"},{\"path\":\"evidence/restore-note.md\",\"bytes\":363,\"sha256\":\"152fd669ba0db738092767a958391964c6fabae95473a2a5472dbce89980f797\"},{\"path\":\"README.md\",\"bytes\":1008,\"sha256\":\"ab2e2aa009836bba164a8003538571a40990cb93312125fda92ecbc5f071be9d\"},{\"path\":\"source-pack/labels.csv\",\"bytes\":60,\"sha256\":\"61ded2b9f447f67160f0bf3489af7649e2a22006e08ad70d0750f142eb671c26\"},{\"path\":\"source-pack/layout.svg\",\"bytes\":196,\"sha256\":\"b9aa5c06bcf8a05976145dae86471ea83d586224aba804afc189c9754460148a\"},{\"path\":\"source-pack/manual.txt\",\"bytes\":122,\"sha256\":\"6dddb3b441ece7f14da54dc4c7f5d98b7ee70980ffcf64a2954c32f9d7854337\"},{\"path\":\"staged-pack/labels.csv\",\"bytes\":44,\"sha256\":\"422074ccffc01b2e417fe655ed8d02b952658d5e6f389bd949a0e85a4d4becfa\"},{\"path\":\"staged-pack/manual.txt\",\"bytes\":122,\"sha256\":\"6dddb3b441ece7f14da54dc4c7f5d98b7ee70980ffcf64a2954c32f9d7854337\"},{\"path\":\"tools/inspect-pack.cjs\",\"bytes\":559,\"sha256\":\"3d2b598950cafbd079a9e66c52cef3a34eb511122352d2cfc255fff932db5c9b\"}];
const root = process.cwd();
const names = ['labels.csv', 'layout.svg', 'manual.txt'];
const digest = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const read = relative => { const file = path.join(root, relative); if ("'!fs.existsSync(file)) return null; assert(fs.statSync(file).isFile(), relative + '"' must be a file'); const buffer = fs.readFileSync(file); return {buffer, bytes:buffer.length, sha256:digest(buffer)}; };
const inventory = JSON.parse(fs.readFileSync(path.join(root, 'audit/inventory.json'), 'utf8'));
assert.deepEqual(Object.keys(inventory).sort(), ['files', 'summary']);
assert(Array.isArray(inventory.files));
assert.equal(inventory.files.length, 3);
const actualFiles = names.map(name => { const source=read('source-pack/'+name); const staged=read('staged-pack/'+name); assert(source, 'Expected source missing: '+name); const status = staged === null ? 'missing' : source.buffer.equals(staged.buffer) ? 'matching' : 'mismatched'; if(staged) assert.equal(status === 'matching', source.bytes === staged.bytes && source.sha256 === staged.sha256); return {path:name, source_bytes:source.bytes, source_sha256:source.sha256, staged_bytes:staged?.bytes??null, staged_sha256:staged?.sha256??null, status}; });
for(let i=0;i<3;i++){ const file=inventory.files[i]; assert.deepEqual(Object.keys(file).sort(), ['path','source_bytes','source_sha256','staged_bytes','staged_sha256','status'].sort()); assert.equal(file.path,names[i]); assert(Number.isSafeInteger(file.source_bytes) && file.source_bytes>=0); assert.match(file.source_sha256,/"'^[0-9a-f]{64}$/); if(file.status==='"'missing'){assert.equal(file.staged_bytes,null);assert.equal(file.staged_sha256,null);}else{assert(Number.isSafeInteger(file.staged_bytes) && file.staged_bytes>=0);assert.match(file.staged_sha256,/"'^[0-9a-f]{64}$/);} assert(['"'matching','mismatched','missing'].includes(file.status)); }
assert.deepEqual(inventory.files, actualFiles);
const actualSummary = {expected_files:3, present_files:actualFiles.filter(f=>f.status"'!=='"'missing').length, matching_files:actualFiles.filter(f=>f.status==='matching').length, mismatched_files:actualFiles.filter(f=>f.status==='mismatched').length, missing_files:actualFiles.filter(f=>f.status==='missing').length};
assert.deepEqual(inventory.summary,actualSummary);
for(const count of Object.values(inventory.summary)) assert(Number.isSafeInteger(count));
assert.equal(actualSummary.expected_files,actualSummary.present_files+actualSummary.missing_files);
assert.equal(actualSummary.present_files,actualSummary.matching_files+actualSummary.mismatched_files);
for(const before of baseline){const after=read(before.path);assert(after,'Supplied file missing: '+before.path);assert.equal(after.bytes,before.bytes,before.path+' length changed');assert.equal(after.sha256,before.sha256,before.path+' hash changed');}
const walk = dir => fs.readdirSync(path.join(root,dir),{withFileTypes:true}).flatMap(entry=>{const relative=dir ? dir+'/'+entry.name : entry.name; assert("'!entry.isSymbolicLink(),'"'Unexpected link: '+relative); return entry.isDirectory()?walk(relative):[relative];});
assert.deepEqual(walk('').sort(), [...baseline.map(file=>file.path),'audit/findings.md','audit/inventory.json'].sort());
assert(fs.readFileSync(path.join(root,'audit/findings.md'),'utf8').includes('Do not rely on the completion'));
process.stdout.write(JSON.stringify({result:'passed', inventory_schema:'exact required keys, ordering, types, hashes, nulls and counts', live_inventory:'all expected paths re-read and matched to recorded lengths, hashes and direct byte comparisons', supplied_files_preserved:baseline.length, only_added_files:['audit/findings.md','audit/inventory.json'], summary:actualSummary},null,2)+'\\n');
'@ | node"
